// GENERATED by scripts/sync-push-shared.mjs from the app source. Do not edit.
import type { Word } from './word.ts';
import { daysSinceEpoch, wordOfDay } from './daily-engine.ts';

/**
 * Welcome words: for someone's first two weeks (from the day they finish
 * onboarding), Today opens on a hand-picked word each day instead of the
 * shared daily one, so first impressions are warm, beautiful and intriguing.
 * This applies to every plan (free, trial and full access). From day 15 on,
 * everyone shares the same daily word again.
 *
 * Days are dealt in this order, skipping any slug that isn't published, so an
 * unpublished word never leaves a gap; the later entries are spares. Keep these
 * off the free shelf, so the free collection below Today still shows every
 * free word.
 */
export const WELCOME_DAYS = 14;

export const WELCOME_SLUGS = [
  'meraki',
  'komorebi',
  'retrouvailles',
  'chrysalism',
  'gumusservi',
  'mamihlapinatapai',
  'gigil',
  'forelsket',
  'hygge',
  'natsukashii',
  'querencia',
  'kintsugi',
  'oubaitori',
  'anam-cara',
  // Spares
  'fika',
  'uitwaaien',
  'reverie',
  'firgun',
  'mudita',
  'tiam',
  'cwtch',
  'ikigai',
] as const;

/** The curated words for days 1–14, in order, from what's published. */
export function welcomeWords(words: readonly Word[]): Word[] {
  const bySlug = new Map(words.map((w) => [w.slug, w]));
  return WELCOME_SLUGS.map((slug) => bySlug.get(slug))
    .filter((w): w is Word => w !== undefined)
    .slice(0, WELCOME_DAYS);
}

/**
 * Today's word for this user: a welcome word during their first two weeks,
 * otherwise the shared daily word. `welcomeDate` is the local date onboarding
 * finished (null for people who joined before this existed).
 */
export function todaysWordFor(
  words: readonly Word[],
  localDate: string,
  welcomeDate: string | null,
): Word | null {
  if (welcomeDate !== null) {
    const day = daysSinceEpoch(localDate) - daysSinceEpoch(welcomeDate);
    if (day >= 0 && day < WELCOME_DAYS) {
      const curated = welcomeWords(words)[day];
      if (curated) return curated;
    }
  }
  return wordOfDay(words, localDate);
}
